const E = 'cubic-bezier(.22,.7,.24,1)';
const SINE = 'cubic-bezier(.45,0,.55,1)';
const VB = '0 0 60.8 103.2', CX = 30.4, CY = 52.2;

const MARKS = [
  { key: 'grid', name: 'Grid', uk: 'Сітка', desc: 'Рівна сітка крапок. Найчистіша й найчиткіша марка.' },
  { key: 'halftone', name: 'Halftone', uk: 'Півтон', desc: 'Крапка більшає до центру кожного штриха — підпис Pilot.' },
  { key: 'contour', name: 'Contour', uk: 'Контур', desc: 'Один-два ряди крапок уздовж контуру. Легка й повітряна.' },
  { key: 'visor', name: 'Visor', uk: 'Забрало', desc: 'Суцільний гребінь, як очі Pilot. Решта — дрібний півтон.' },
  { key: 'rings', name: 'Rings', uk: 'Кільця', desc: 'Концентричні кола крапок, обрізані формою. Радарний ритм.' },
];

const hash = (i) => { const s = Math.sin(i * 127.1 + 311.7) * 43758.5453; return s - Math.floor(s); };

function markSVG(mi) {
  const m = MARK_DATA[mi];
  let body = '';
  for (let p = 0; p < 5; p++) {
    body += `<g class="piece" data-p="${p}">`;
    if (m.solid.includes(p)) body += `<path class="solid" d="${PIECES[p]}"/>`;
    for (const d of m.dots) if (d[3] === p) body += `<circle class="dot" cx="${d[0]}" cy="${d[1]}" r="${d[2]}"/>`;
    body += '</g>';
  }
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="${VB}" aria-hidden="true"><g class="root" fill="currentColor">${body}</g></svg>`;
}

function itemsOf(svg, mi) {
  const m = MARK_DATA[mi];
  const items = [...svg.querySelectorAll('.dot')].map((el, i) => {
    const [x, y, r, p, d, k] = m.dots[i];
    return { el, x, y, r, p, d, k, solid: false };
  });
  svg.querySelectorAll('.solid').forEach((el) => {
    const p = +el.parentNode.dataset.p, b = PIECE_BOX[p];
    items.push({ el, x: (b[0] + b[2]) / 2, y: (b[1] + b[3]) / 2, r: 3, p, d: 3, k: -1, solid: true });
  });
  let maxRad = 0, maxD = 0;
  items.forEach((t, i) => {
    const dx = t.x - CX, dy = t.y - CY;
    t.dist = Math.hypot(dx, dy);
    t.ang = (Math.atan2(dx, -dy) / (Math.PI * 2) + 1) % 1; // 0 at top, clockwise
    t.nx = t.x / 60.8; t.ny = t.y / 103.2;
    t.rnd = hash(i + mi * 997);
    if (t.k < 0) t.k = t.ang;
    maxRad = Math.max(maxRad, t.dist); if (!t.solid) maxD = Math.max(maxD, t.d);
  });
  items.forEach((t) => { t.rad = t.dist / maxRad; t.dn = Math.min(1, t.d / maxD); });
  return items;
}

function makeCtx(stage, mi) {
  const svg = stage.querySelector('svg');
  const ctx = {
    svg, mi, root: svg.querySelector('.root'), pieces: [...svg.querySelectorAll('.piece')],
    motions: [], shots: [], hold: false,
  };
  ctx.items = itemsOf(svg, mi);
  ctx.dots = ctx.items.filter((t) => !t.solid);
  ctx.add = (el, frames, { dur = 2400, delay = 0, iter = Infinity } = {}) => {
    const fr = frames.map((f) => ('easing' in f ? f : { ...f, easing: E }));
    const a = el.animate(fr, { duration: dur, delay, iterations: iter, fill: 'both' });
    a.playbackRate = speed; a.pause(); ctx.motions.push(a); return a;
  };
  return ctx;
}

// scale that stays subtle on solid pieces
const sc = (t, s) => `scale(${t.solid ? 1 + (s - 1) * 0.06 : s})`;
// continuous travelling bump: element peaks at phase * dur within each loop
function wave(c, t, phase, dur, lo, hi, rise = 0.06, fall = 0.32, ease = E) {
  return c.add(t.el, [
    { ...lo, offset: 0, easing: ease }, { ...hi, offset: rise, easing: ease },
    { ...lo, offset: Math.min(rise + fall, 0.99) }, { ...lo, offset: 1 },
  ], { dur, delay: (phase - 1) * dur });
}
// entrance: hidden -> settled, then the whole svg fades for a clean loop
function enter(c, dur, list) {
  for (const { el, phase, from, over, len = 0.2 } of list) {
    const s = 0.03 + phase, e = Math.min(s + len, 0.84);
    const fr = [{ ...from, offset: 0 }, { ...from, offset: s }];
    if (over) fr.push({ ...over, offset: s + (e - s) * 0.6 });
    fr.push({ opacity: 1, transform: 'none', offset: e }, { opacity: 1, transform: 'none', offset: 1 });
    c.add(el, fr, { dur });
  }
}
const loopFade = (c, dur) => c.add(c.svg, [
  { opacity: 1, offset: 0 }, { opacity: 1, offset: 0.88 }, { opacity: 0, offset: 0.97 }, { opacity: 0, offset: 1 },
], { dur });
const pivot = (el, x, y) => { el.style.transformBox = 'view-box'; el.style.transformOrigin = `${x}px ${y}px`; };

// ---------- shared by the Halftone series
const FROM5 = ['translate(-14px,22px) rotate(10deg)', 'translate(14px,22px) rotate(-10deg)', 'translateY(-26px)', 'translate(-22px,-6px) rotate(-12deg)', 'translate(22px,-6px) rotate(12deg)'];
// a small counter-move past the target before settling
const overshoot = (f, k = -0.05) => f.replace(/-?[\d.]+/g, (n) => String(+n * k));
function assemble(c, D, phase = [0.16, 0.16, 0, 0.08, 0.08], len = 0.3, from = FROM5) {
  enter(c, D, c.pieces.map((el, p) => ({ el, phase: phase[p], len, from: { opacity: 0, transform: from[p] }, over: { opacity: 1, transform: overshoot(from[p]) } })));
}
// one or more diagonal light sweeps over every dot; the crest flares most. at = loop positions (0..1) where each sweep starts
function glint(c, D, at, { width = 0.42, lo = 0.7, hi = 1.15, crest = 1.45, dx = 0.55, dy = 0.45, tail = 0.22, rev = [] } = {}) {
  c.items.forEach((t) => {
    const a = { opacity: lo, transform: 'scale(1)' }, b = { opacity: 1, transform: sc(t, t.p === 2 ? crest : hi) };
    const fr = [{ ...a, offset: 0 }];
    let last = 0;
    at.forEach((p, i) => {
      const x = rev[i] ? 1 - t.nx : t.nx;
      const st = Math.max(last + 0.001, Math.min(0.9, p + (x * dx + t.ny * dy) * width));
      const pk = Math.min(st + 0.05, 0.97), end = Math.min(st + tail, 0.985);
      if (end <= pk) return;
      fr.push({ ...a, offset: st }, { ...b, offset: pk }, { ...a, offset: end });
      last = end;
    });
    fr.push({ ...a, offset: 1 });
    c.add(t.el, fr, { dur: D });
  });
}

// ---------- shared by the Hard assembly series: slams, impact shake, hard flash
const SLAM = 'cubic-bezier(.95,0,1,.6)';   // accelerates into the hit, no ease-out
const SNAP = 'steps(1,end)';
// pieces fly in on straight lines and hit at their slot; at = loop position of each hit
function slam(c, D, at, from, travel = 0.07) {
  c.pieces.forEach((el, p) => {
    const hit = at[p], go = Math.max(0.001, hit - travel);
    c.add(el, [
      { opacity: 0, transform: from[p], offset: 0, easing: SNAP }, { opacity: 0, transform: from[p], offset: go - 0.0005, easing: SNAP },
      { opacity: 1, transform: from[p], offset: go, easing: SLAM }, { opacity: 1, transform: overshoot(from[p], -0.04), offset: hit, easing: SNAP },
      { opacity: 1, transform: 'none', offset: Math.min(hit + 0.012, 0.99) }, { opacity: 1, transform: 'none', offset: 1 },
    ], { dur: D });
  });
}
// recoil of the whole mark at each hit: a hard jolt, two smaller ones, still
function shake(c, D, hits, amp = 2.2) {
  const fr = [{ transform: 'none', offset: 0 }];
  let last = 0;
  hits.forEach(([at, k = 1]) => {
    if (at <= last + 0.01) return;
    const a = amp * k;
    fr.push({ transform: 'none', offset: at - 0.001 },
      { transform: `translate(${a}px,${-a * 0.6}px)`, offset: at + 0.006 },
      { transform: `translate(${-a * 0.7}px,${a * 0.4}px)`, offset: at + 0.014 },
      { transform: `translate(${a * 0.35}px,0)`, offset: at + 0.022 },
      { transform: 'none', offset: at + 0.032 });
    last = at + 0.032;
  });
  fr.push({ transform: 'none', offset: 1 });
  c.add(c.root, fr, { dur: D, easing: SNAP });
}
// every dot flares at once for a frame, then drops back: a muzzle-flash read of the impact
function flash(c, D, at, len = 0.05, base = 0.85) {
  c.items.forEach((t) => {
    const a = { opacity: base, transform: 'scale(1)' };
    c.add(t.el, [{ ...a, offset: 0 }, { ...a, offset: at }, { opacity: 1, transform: sc(t, 1.55), offset: at + 0.006, easing: SNAP },
      { opacity: 1, transform: sc(t, 1.2), offset: at + len * 0.5 }, { ...a, offset: at + len }, { ...a, offset: 1 }], { dur: D });
  });
}

