// ---------- page
const grid = document.querySelector('#grid'), dialog = document.querySelector('#preview');
const largeStage = document.querySelector('#large-stage');
const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
let speed = 1, paused = reduce, selected = 0, markOverride = -1, dialogMark = null;
let favorites;
try { favorites = new Set(JSON.parse(localStorage.getItem('garuda-motion-favorites') || '[]')); } catch { favorites = new Set(); }
const instances = [];
const pad = (n) => String(n).padStart(2, '0');

function teardown(x) {
  if (!x.ctx) return;
  x.ctx.motions.forEach((a) => a.cancel()); x.ctx.shots.forEach((a) => a.cancel());
  x.ctx = null;
}
function build(x) { teardown(x); x.stage.innerHTML = markSVG(x.mark); }
function ensure(x) { if (!x.ctx) { x.ctx = makeCtx(x.stage, x.mark); ANIMS[x.index][4](x.ctx); } }
function sync() {
  for (const x of instances) {
    const run = !paused && !document.hidden && x.visible && (!dialog.open || x.large);
    if (run) ensure(x);
    if (!x.ctx) continue;
    for (const a of x.ctx.motions) { a.playbackRate = speed; if (run && !x.ctx.hold) a.play(); else a.pause(); }
  }
  const label = paused ? 'Відтворити' : 'Пауза';
  document.querySelector('#pause').textContent = label;
  document.querySelector('#preview-pause').textContent = label;
}
function replay(x) { if (x && x.ctx) x.ctx.motions.forEach((a) => { a.currentTime = 0; }); sync(); }

function updateFavorites() {
  document.querySelector('#favorites').textContent = favorites.size
    ? 'Обране: ' + [...favorites].sort((a, b) => a - b).map((i) => `${pad(i + 1)} ${ANIMS[i][0]}`).join(' · ') : '';
  try { localStorage.setItem('garuda-motion-favorites', JSON.stringify([...favorites])); } catch { /* storage unavailable */ }
}

// five static marks
const marksEl = document.querySelector('#marks');
MARKS.forEach((m, i) => {
  const sizes = [20, 32, 48].map((h) => markSVG(i).replace('<svg ', `<svg style="height:${h}px" `)).join('');
  marksEl.insertAdjacentHTML('beforeend', `<article class="mark-card"><div class="big">${markSVG(i)}</div><div class="sizes" aria-label="20, 32 і 48 px">${sizes}</div><div class="mark-meta"><div><span class="number">M${i + 1} · ${MARK_DATA[i].dots.length} крапок</span><h3>${m.uk} <span style="color:#6f7580;font-weight:400">/ ${m.name}</span></h3><p>${m.desc}</p></div><a href="./marks/garuda-${m.key}.svg" download>SVG ↓</a></div></article>`);
});
const select = document.querySelector('#mark-select');
MARKS.forEach((m, i) => select.insertAdjacentHTML('beforeend', `<option value="${i}">${m.uk}</option>`));
const switcher = document.querySelector('#mark-switch');
MARKS.forEach((m, i) => switcher.insertAdjacentHTML('beforeend', `<button data-mark="${i}" aria-pressed="false">${m.uk}</button>`));
['#count-all', '#count-intro', '#count-eyebrow'].forEach((s) => { document.querySelector(s).textContent = ANIMS.length; });

const observer = new IntersectionObserver((entries) => {
  for (const e of entries) { const x = instances.find((y) => y.card === e.target); if (x) x.visible = e.isIntersecting; }
  sync();
}, { threshold: 0.15 });

ANIMS.forEach(([name, category, mark, description], i) => {
  const card = document.createElement('article');
  card.className = 'card'; card.dataset.category = category;
  card.innerHTML = `<button class="stage-button" aria-label="Переглянути ${pad(i + 1)} ${name}"><span class="stage"></span></button><button class="replay" aria-label="Повторити ${name}">↻</button><button class="star" aria-label="Обрати ${name}" aria-pressed="${favorites.has(i)}">☆</button><div class="card-meta"><span class="number">${pad(i + 1)} / ${ANIMS.length}</span><h2>${name}</h2><p>${description}</p><div class="tags"><span class="tag">${category}</span><span class="tag mark"></span></div></div>`;
  grid.append(card);
  const x = { card, index: i, native: mark, mark, stage: card.querySelector('.stage'), visible: false, ctx: null };
  card.querySelector('.tag.mark').textContent = MARKS[mark].uk;
  build(x); instances.push(x);
  card.querySelector('.stage-button').onclick = () => open(i);
  card.querySelector('.replay').onclick = () => replay(x);
  card.querySelector('.star').onclick = (e) => {
    favorites.has(i) ? favorites.delete(i) : favorites.add(i);
    e.currentTarget.setAttribute('aria-pressed', String(favorites.has(i)));
    e.currentTarget.textContent = favorites.has(i) ? '★' : '☆';
    updateFavorites();
  };
  if (favorites.has(i)) card.querySelector('.star').textContent = '★';
  observer.observe(card);
});

function large() { return instances.find((x) => x.large); }
function open(i) {
  selected = (i + ANIMS.length) % ANIMS.length;
  const old = large();
  if (old) { teardown(old); instances.splice(instances.indexOf(old), 1); }
  const [name, category, native, description] = ANIMS[selected];
  const mark = dialogMark ?? (markOverride < 0 ? native : markOverride);
  document.querySelector('#preview-label').textContent = `${pad(selected + 1)} / ${category.toUpperCase()}`;
  document.querySelector('#preview-title').textContent = name;
  document.querySelector('#preview-description').textContent = description;
  switcher.querySelectorAll('button').forEach((b) => b.setAttribute('aria-pressed', String(+b.dataset.mark === mark)));
  const x = { large: true, visible: true, index: selected, mark, stage: largeStage, ctx: null };
  build(x); instances.push(x);
  if (!dialog.open) dialog.showModal();
  sync();
}
switcher.addEventListener('click', (e) => {
  const b = e.target.closest('[data-mark]'); if (!b) return;
  dialogMark = +b.dataset.mark; open(selected);
});
dialog.addEventListener('close', () => {
  if (dialog.open) return; // reopened before the async close event fired
  const x = large(); if (x) { teardown(x); instances.splice(instances.indexOf(x), 1); }
  dialogMark = null; sync();
});
dialog.addEventListener('keydown', (e) => {
  if (e.key === 'ArrowLeft') open(selected - 1);
  if (e.key === 'ArrowRight') open(selected + 1);
});
document.querySelector('#close').onclick = () => dialog.close();
document.querySelector('#previous').onclick = () => open(selected - 1);
document.querySelector('#next').onclick = () => open(selected + 1);
document.querySelector('#preview-pause').onclick = () => { paused = !paused; sync(); };
document.querySelector('#preview-replay').onclick = () => replay(large());
document.querySelector('#pause').onclick = () => { paused = !paused; sync(); };
document.querySelector('#replay').onclick = () => instances.forEach(replay);
document.querySelector('#speed').onchange = (e) => { speed = Number(e.target.value); sync(); };
select.onchange = () => {
  markOverride = Number(select.value);
  instances.filter((x) => !x.large).forEach((x) => {
    x.mark = markOverride < 0 ? x.native : markOverride;
    x.card.querySelector('.tag.mark').textContent = MARKS[x.mark].uk;
    build(x);
  });
  sync();
};
document.querySelectorAll('[data-filter]').forEach((button) => {
  button.onclick = () => {
    document.querySelectorAll('[data-filter]').forEach((b) => b.setAttribute('aria-pressed', String(b === button)));
    const f = button.dataset.filter;
    instances.filter((x) => !x.large).forEach((x) => {
      x.card.hidden = f === 'favorites' ? !favorites.has(x.index) : f !== 'all' && x.card.dataset.category !== f;
      if (x.card.hidden) x.visible = false;
    });
    sync();
  };
});
document.addEventListener('visibilitychange', sync);
if (reduce) document.querySelector('#motion-note').textContent = 'Зменшення руху увімкнено: показано статичні марки. Натисніть «Відтворити», щоб переглянути анімації.';
// the owner picked the Halftone mark: show it on every card by default
select.value = '1'; select.onchange();
sync(); updateFavorites();
